import 'insight.dart';

/// A curated practice puzzle: a position with one clear answer.
/// The library in lib/puzzles/library.dart is generated by tool/curate.py;
/// test/puzzle_library_test.dart re-rates every entry with the real engine.
class Puzzle {
  final String id;
  final String fen;

  /// Winning first moves in UCI, sorted. Any of them solves the puzzle.
  final List<String> solutions;

  /// The first solution in standard algebraic notation.
  final String san;

  /// The idea the solution needs; null for a mate in 2 or 3.
  final Idea? idea;

  /// 1 to 3 for a forced mate, 0 for a material puzzle.
  final int mateIn;

  /// Difficulty tier, 1 (easiest) to 5.
  final int tier;

  /// Plain-words reason the solution works.
  final String text;

  /// Where the position came from: 'hand' or a game id.
  final String source;

  const Puzzle({
    required this.id,
    required this.fen,
    required this.solutions,
    required this.san,
    required this.idea,
    required this.mateIn,
    required this.tier,
    required this.text,
    required this.source,
  });
}
